import SwiftUI

struct CosmeticCraftingView: View {

    @ObservedObject var gamificationViewModel: GamificationViewModel

    // MARK: - Cosmetic Collections

    private enum CosmeticCollection: String, CaseIterable, Identifiable {

        case astral
        case nature
        case cyber

        var id: String {
            rawValue
        }

        var title: String {
            rawValue.capitalized
        }
    }

    // MARK: - View State

    @State private var selectedCollection: CosmeticCollection = .astral

    @State private var hasLoaded = false

    @State private var selectedCosmetic: CosmeticDefinition?

    @State private var showCraftConfirmation = false

    @State private var showCraftResult = false

    @State private var resultTitle = ""
    @State private var resultMessage = ""

    // MARK: - Filtered Cosmetic Catalog

    private var displayedCosmetics: [CosmeticDefinition] {

        gamificationViewModel.cosmeticCatalog
            .filter {
                $0.collection == selectedCollection.rawValue
            }
            .sorted {
                $0.sort_order < $1.sort_order
            }
    }

    // MARK: - Main View

    var body: some View {

        ScrollView {

            VStack(alignment: .leading, spacing: 20) {

                // MARK: - Introduction

                VStack(alignment: .leading, spacing: 6) {

                    Text("Craft Your Style")
                        .font(.title2)
                        .fontWeight(.bold)

                    Text(
                        "Use earned materials to permanently unlock avatars, profile frames, and app themes."
                    )
                    .font(.subheadline)
                    .foregroundColor(.secondary)
                }

                // MARK: - Material Balances

                VStack(alignment: .leading, spacing: 12) {

                    Text("Your Materials")
                        .font(.headline)

                    ScrollView(.horizontal, showsIndicators: false) {

                        HStack(spacing: 12) {

                            ForEach(
                                gamificationViewModel.materialsInventory
                            ) { material in

                                VStack(alignment: .leading, spacing: 6) {

                                    Text(material.name)
                                        .font(.caption)
                                        .foregroundColor(.secondary)

                                    Text(material.quantity.formatted())
                                        .font(.title3)
                                        .fontWeight(.bold)
                                }
                                .padding(12)
                                .frame(minWidth: 125, alignment: .leading)
                                .background(
                                    Color(.secondarySystemGroupedBackground)
                                )
                                .cornerRadius(12)
                            }
                        }
                    }
                }

                // MARK: - Collection Picker

                VStack(alignment: .leading, spacing: 12) {

                    Text("Cosmetic Collections")
                        .font(.headline)

                    Picker(
                        "Collection",
                        selection: $selectedCollection
                    ) {

                        ForEach(CosmeticCollection.allCases) { collection in

                            Text(collection.title)
                                .tag(collection)
                        }
                    }
                    .pickerStyle(.segmented)
                }

                // MARK: - Cosmetic Catalog

                if !hasLoaded {

                    HStack {

                        Spacer()

                        ProgressView("Loading cosmetics...")

                        Spacer()
                    }
                    .padding(.vertical, 30)

                } else if gamificationViewModel.cosmeticCatalog.isEmpty {

                    VStack(spacing: 12) {

                        Image(systemName: "hammer.circle")
                            .font(.largeTitle)
                            .foregroundColor(.secondary)

                        Text("No Cosmetics Available")
                            .font(.headline)

                        Text(
                            gamificationViewModel.cosmeticError ??
                            "There are no available cosmetics right now."
                        )
                        .font(.subheadline)
                        .foregroundColor(.secondary)
                        .multilineTextAlignment(.center)

                        Button("Retry") {

                            Task {

                                await gamificationViewModel.refreshCosmeticData()
                            }
                        }
                        .buttonStyle(.bordered)
                    }
                    .frame(maxWidth: .infinity)
                    .padding(.vertical, 30)

                } else if displayedCosmetics.isEmpty {

                    Text("No cosmetics are available in this collection.")
                        .foregroundColor(.secondary)

                } else {

                    LazyVStack(spacing: 16) {

                        ForEach(displayedCosmetics) { cosmetic in

                            cosmeticCard(cosmetic)
                        }
                    }
                }
            }
            .padding()

        } // Closes ScrollView

        
        // MARK: - Apply Equipped App Theme

        .modifier(
            ProjectHealthThemeModifier(
                gamificationViewModel: gamificationViewModel
            )
        )

        
        .navigationTitle("Cosmetic Crafting")
        .navigationBarTitleDisplayMode(.inline)

        // MARK: - Load Catalog

        .task {

            await gamificationViewModel.refreshCosmeticData()

            hasLoaded = true
        }

        // MARK: - Pull to Refresh

        .refreshable {

            await gamificationViewModel.refreshCosmeticData()
        }

        // MARK: - Craft Confirmation

        .confirmationDialog(
            "Confirm Crafting",
            isPresented: $showCraftConfirmation,
            titleVisibility: .visible
        ) {

            if let cosmetic = selectedCosmetic {

                Button("Craft \(cosmetic.name)") {

                    Task {

                        let wasCrafted =
                            await gamificationViewModel.craftCosmetic(
                                cosmeticID: cosmetic.id
                            )

                        resultTitle = wasCrafted
                            ? "Crafting Complete!"
                            : "Unable to Craft"

                        resultMessage =
                            gamificationViewModel.cosmeticNotice ??
                            gamificationViewModel.cosmeticError ??
                            "Please refresh your inventory and try again."

                        showCraftResult = true
                    }
                }
            }

            Button("Cancel", role: .cancel) {}

        } message: {

            if let cosmetic = selectedCosmetic {

                Text(
                    "Spend \(recipeSummary(for: cosmetic.id)) to permanently unlock \(cosmetic.name)?"
                )
            }
        }

        // MARK: - Craft Result

        .alert(
            resultTitle,
            isPresented: $showCraftResult
        ) {

            Button("OK", role: .cancel) {}

        } message: {

            Text(resultMessage)
        }

    } // Closes body


    // MARK: - Cosmetic Card

    private func cosmeticCard(
        _ cosmetic: CosmeticDefinition
    ) -> some View {

        VStack(alignment: .leading, spacing: 14) {

            // MARK: - Cosmetic Information

            HStack(spacing: 14) {

                
                Image(cosmetic.asset_key)
                    .resizable()
                    .aspectRatio(
                        contentMode: cosmetic.cosmetic_type == "frame"
                            ? .fit
                            : .fill
                    )
                    .frame(width: 70, height: 70)
                    .background(
                        collectionColor(for: cosmetic.collection)
                            .opacity(0.12)
                    )
                    .clipShape(
                        RoundedRectangle(cornerRadius: 12)
                    )


                VStack(alignment: .leading, spacing: 5) {

                    Text(cosmetic.name)
                        .font(.headline)

                    Text(cosmetic.cosmetic_type.capitalized)
                        .font(.caption)
                        .foregroundColor(.secondary)

                    Text(cosmetic.description)
                        .font(.caption)
                        .foregroundColor(.secondary)
                }

                Spacer()
            }

            Divider()

            // MARK: - Recipe Ingredients

            Text("Required Materials")
                .font(.subheadline)
                .fontWeight(.semibold)

            ForEach(
                gamificationViewModel.ingredients(for: cosmetic.id),
                id: \.resource_id
            ) { ingredient in

                HStack {

                    Image(systemName: "diamond.fill")
                        .font(.caption)
                        .foregroundColor(.secondary)

                    Text(ingredient.resource_definitions.name)
                        .font(.subheadline)

                    Spacer()

                    Text(
                        "\(availableQuantity(for: ingredient.resource_id)) / \(ingredient.quantity)"
                    )
                    .font(.subheadline)
                    .fontWeight(.medium)
                    .foregroundColor(
                        availableQuantity(for: ingredient.resource_id)
                            >= ingredient.quantity
                        ? .green
                        : .red
                    )
                }
            }

            // MARK: - Craft Button

            Button {

                selectedCosmetic = cosmetic
                showCraftConfirmation = true

            } label: {

                HStack {

                    Spacer()

                    if gamificationViewModel.isCraftingCosmetic {

                        ProgressView()
                            .tint(.white)

                    } else if gamificationViewModel.ownsCosmetic(cosmetic.id) {

                        Image(systemName: "checkmark.circle.fill")

                    } else {

                        Image(systemName: "hammer.fill")
                    }

                    Text(craftButtonTitle(for: cosmetic))
                        .fontWeight(.semibold)

                    Spacer()
                }
                .padding(.vertical, 6)
            }
            .buttonStyle(.borderedProminent)
            .disabled(
                !gamificationViewModel.canCraftCosmetic(cosmetic.id)
            )
        }
        .padding()
        .background(
            Color(.secondarySystemGroupedBackground)
        )
        .cornerRadius(16)
    }


    // MARK: - Available Material Quantity

    private func availableQuantity(
        for resourceID: UUID
    ) -> Int64 {

        gamificationViewModel.materialsInventory.first {
            $0.id == resourceID
        }?.quantity ?? 0
    }


    // MARK: - Craft Button Title

    private func craftButtonTitle(
        for cosmetic: CosmeticDefinition
    ) -> String {

        if gamificationViewModel.ownsCosmetic(cosmetic.id) {
            return "Owned"
        }

        if gamificationViewModel.isCraftingCosmetic {
            return "Crafting..."
        }

        if gamificationViewModel.canCraftCosmetic(cosmetic.id) {
            return "Craft"
        }

        return "Not Enough Materials"
    }


    // MARK: - Recipe Summary

    private func recipeSummary(
        for cosmeticID: UUID
    ) -> String {

        let ingredients =
            gamificationViewModel.ingredients(for: cosmeticID)

        return ingredients
            .map {
                "\($0.quantity) \($0.resource_definitions.name)"
            }
            .joined(separator: " + ")
    }


    // MARK: - Collection Colors

    private func collectionColor(
        for collection: String
    ) -> Color {

        switch collection {

        case "astral":
            return .purple

        case "nature":
            return .green

        case "cyber":
            return .cyan

        default:
            return .secondary
        }
    }

} // Closes CosmeticCraftingView


